.in-app-notification-container {
  position: relative;
  inline-size: 288px;
  background: var(--container-background);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  border: 1px solid var(--container-border);
  border-radius: 6px;
  box-shadow: 0 2px 6px -2px rgba(0, 0, 0, 0.25);
  overflow: clip;

  & .in-app-notification-content {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 6px;
    border: 1px solid var(--content-border);
    border-radius: 5px;
    color: var(--text);
    padding: var(--notification-padding);
    padding-inline-start: calc(var(--notification-padding) + 42px);
    isolation: isolate;
    background: var(--content-background);

    &:dir(rtl)::before {
      transform: scaleX(-1);
    }

    .in-app-notification-heading,
    .in-app-notification-description-wrapper {
      padding-inline-end: var(--content-padding-inline-end);
    }
  }

& button[is="in-app-notification-close-button"] {
  position: absolute;
  inset-block-start: var(--notification-padding);
  inset-inline-end: var(--notification-padding);
  background: var(--close-button-background);
  border: 1px solid var(--close-button-border);
  border-radius: 50%;
  color: var(--close-button-text);
  block-size: 20px;
  inline-size: 20px;
  margin: 0;
  padding: 0;
  -moz-context-properties: fill, stroke;
  fill: currentColor;
  stroke: currentColor;
  z-index: 10;
  display: flex;
  justify-content: center;
  align-items: center;

& .in-app-notification-description {
  color: var(--text);
  font-size: 0.9rem;
  min-block-size: 2lh;
  margin: 0;
  hyphens: auto;
  max-block-size: 20lh;
  overflow: auto;
}

& .icon {
  position: absolute;
  z-index: 9;
  pointer-events: none;
  content: var(--icon-url);
  -moz-context-properties: fill, stroke;
  fill: var(--icon-fill);
  stroke: var(--icon-stroke);

  &:dir(rtl) {
    transform: scaleX(-1);
  }
